package android.content.pm;
public class PackageManager {
 public static boolean failOwner;
 public String[] getPackagesForUid(int uid){
  if(uid==77777&&failOwner)throw new IllegalStateException("PM unavailable");
  return switch(uid){
   case 10197,110197 -> new String[]{"shared.systemui.peer","com.android.systemui"};
   case 10151 -> new String[]{"com.miui.screenshot"};
   case 1000 -> new String[]{"android","miui.systemui.plugin"};
   case 55555 -> null;
   case 66666 -> new String[]{};
   default -> new String[]{"com.android.systemui.fake"};};
 }
}

